package com.interview.mysqlescdc.verifier.rebuild;
import java.nio.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.TopicPartition;import org.apache.kafka.common.serialization.StringDeserializer;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import tools.jackson.databind.json.JsonMapper;
@Component public final class KafkaBarrierObserver implements BarrierObserver{private final String bootstrap;private final JsonMapper json=JsonMapper.builder().build();public KafkaBarrierObserver(@Value("${lab.kafka-bootstrap-servers:localhost:29092}")String bootstrap){this.bootstrap=bootstrap;}
 public Map<TopicPartition,Long> awaitAll(String topic,Barrier barrier,Map<TopicPartition,Long> starts,Duration timeout){List<TopicPartition> partitions=List.of(new TopicPartition(topic,0),new TopicPartition(topic,1),new TopicPartition(topic,2));if(!starts.keySet().equals(Set.copyOf(partitions))||!barrier.partitionTokens().equals(Set.of("0","1","2")))throw new IllegalArgumentException("exact partition vector required");var found=new HashMap<TopicPartition,Long>();try(var consumer=new KafkaConsumer<String,String>(properties())){consumer.assign(partitions);starts.forEach(consumer::seek);Instant deadline=Instant.now().plus(timeout);while(Instant.now().isBefore(deadline)&&found.size()<3){for(var record:consumer.poll(Duration.ofMillis(200))){var root=json.readTree(record.value());if(!"cdc_barrier".equals(root.path("table").asText()))continue;for(var row:root.path("data")){String token=row.path("partition_token").asText();UUID run=decode(row.path("run_id").asText());if(!barrier.runId().equals(run))continue;if(record.key()!=null||!token.equals(Integer.toString(record.partition()))||Math.floorMod(token.hashCode(),3)!=record.partition())throw new IllegalStateException("barrier routing mismatch");TopicPartition tp=new TopicPartition(record.topic(),record.partition());if(found.putIfAbsent(tp,record.offset()+1)!=null)throw new IllegalStateException("duplicate barrier token");}}}if(found.size()!=3)throw new IllegalStateException("barrier observation timeout");return Map.copyOf(found);}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("barrier observation failed",e);}}
 private Properties properties(){Properties p=new Properties();p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG,bootstrap);p.put(ConsumerConfig.GROUP_ID_CONFIG,"rebuild-barrier-observer-"+UUID.randomUUID());p.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG,"false");p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG,"none");p.put(ConsumerConfig.ISOLATION_LEVEL_CONFIG,"read_committed");p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG,StringDeserializer.class);p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,StringDeserializer.class);return p;}
 private static UUID decode(String value){byte[] bytes=value.getBytes(StandardCharsets.ISO_8859_1);if(bytes.length!=16)throw new IllegalStateException("barrier run identity mismatch");ByteBuffer b=ByteBuffer.wrap(bytes);return new UUID(b.getLong(),b.getLong());}}
